import{_ as l,C as r,o as a,c as n,a2 as s,b as i,w as o,a as d,E as p,a3 as c}from"./chunks/framework.BQq6mqvm.js";const k=JSON.parse('{"title":"系统管理","description":"","frontmatter":{},"headers":[],"relativePath":"admin/settings.md","filePath":"admin/settings.md","lastUpdated":1790385461000}'),h={name:"admin/settings.md"};function g(u,t,b,m,E,B){const e=r("Mermaid");return a(),n("div",null,[t[1]||(t[1]=s(`<h1 id="系统管理" tabindex="-1">系统管理 <a class="header-anchor" href="#系统管理" aria-label="Permalink to &quot;系统管理&quot;">​</a></h1><p>在左侧菜单进入<strong>系统管理</strong>。这里分两块：上面是上传策略，下面是存储一致性检查。</p><p>上传策略的修改<strong>保存后立即生效</strong>，无需重启服务。</p><h2 id="单文件最大体积" tabindex="-1">单文件最大体积 <a class="header-anchor" href="#单文件最大体积" aria-label="Permalink to &quot;单文件最大体积&quot;">​</a></h2><p>限制单个文件的大小，默认 <strong>500 MB</strong>，可设置 1 ~ 102400 MB。</p><p>超出限制的文件会在<strong>开始上传前</strong>就被拒绝，不会占用服务器空间。</p><h2 id="允许上传的文件类型" tabindex="-1">允许上传的文件类型 <a class="header-anchor" href="#允许上传的文件类型" aria-label="Permalink to &quot;允许上传的文件类型&quot;">​</a></h2><p>有两种模式：</p><ul><li><strong>允许所有文件类型</strong>（默认）—— 不做任何限制。</li><li><strong>只允许指定类型</strong> —— 填写允许的扩展名，例如 <code>pdf,docx,xlsx,png,jpg</code>。</li></ul><p>填写时格式很宽松：可以用逗号、分号、空格或顿号分隔，大小写不限，前面的点可写可不写。例如下面这些写法效果相同：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pdf,docx,xlsx</span></span>
<span class="line"><span>.PDF .Docx .XLSX</span></span>
<span class="line"><span>pdf、docx、xlsx</span></span></code></pre></div><p>页面提供了几个常用预设（仅文档与图片、仅图片、压缩包与文档），点一下即可填入。</p><div class="tip custom-block"><p class="custom-block-title">留空 = 允许全部</p><p>把输入框清空，就恢复为允许所有类型。</p></div><h2 id="文件保留天数" tabindex="-1">文件保留天数 <a class="header-anchor" href="#文件保留天数" aria-label="Permalink to &quot;文件保留天数&quot;">​</a></h2><p>文件上传后经过多少天自动删除（进入回收站），默认 <strong>15 天</strong>，可设置 1 ~ 3650 天。</p><p>修改后：</p><ul><li><strong>新上传</strong>的文件按新天数计算到期时间。</li><li><strong>已上传</strong>的文件仍按原来的到期时间生效。</li></ul><h2 id="回收站保留天数" tabindex="-1">回收站保留天数 <a class="header-anchor" href="#回收站保留天数" aria-label="Permalink to &quot;回收站保留天数&quot;">​</a></h2><p>文件进入回收站后继续保留多少天，默认 <strong>7 天</strong>，可设置 0 ~ 365 天。</p><ul><li>保留期内，管理员可以在<a href="./files">文件与回收站</a>中恢复文件。</li><li>保留期结束后，文件会被<strong>彻底删除</strong>（磁盘文件与记录一并删除，不可恢复）。</li><li>设为 <code>0</code> 表示进入回收站后立即彻底删除。</li></ul><h2 id="分片大小" tabindex="-1">分片大小 <a class="header-anchor" href="#分片大小" aria-label="Permalink to &quot;分片大小&quot;">​</a></h2><p>大文件分片上传时每片的大小，默认 <strong>4 MB</strong>，可设置 1 ~ 64 MB。</p><p>一般不需要调整。网络较差的场景可以调小，内网高速环境可以调大。</p><p>修改只影响<strong>新的</strong>上传任务，进行中的任务不受影响。</p><h2 id="可预览上限" tabindex="-1">可预览上限 <a class="header-anchor" href="#可预览上限" aria-label="Permalink to &quot;可预览上限&quot;">​</a></h2><p>限制<strong>能在线预览</strong>的文件大小，默认 <strong>20 MB</strong>，可设置 0 ~ 102400 MB。</p><p>预览要把整个文件读到浏览器里再解析，文件太大容易把页面卡住甚至卡死，所以单独设一道闸。</p><p>超出上限的文件：</p><ul><li>点预览会提示「超过在线预览上限，请下载后查看」，<strong>不会</strong>去加载内容；</li><li><strong>下载完全不受影响</strong> —— 下载到本地照常打开。</li></ul><div class="tip custom-block"><p class="custom-block-title">设为 0 表示不限制</p><p>填 <code>0</code> 就是关掉这道闸，多大都能在线预览。内网带宽充足、机器性能好时可以这么设。</p></div><div class="warning custom-block"><p class="custom-block-title">这只是预览的闸，不是上传的闸</p><p>「单文件最大体积」决定<strong>能不能传上来</strong>，这个决定<strong>能不能在线看</strong>。两个互不影响。</p></div><h2 id="永久空间配额" tabindex="-1">永久空间配额 <a class="header-anchor" href="#永久空间配额" aria-label="Permalink to &quot;永久空间配额&quot;">​</a></h2><p>「设为永久」的文件永远不会被自动清理，所以给这类文件总量封一个上限，默认 <strong>100 GB</strong>，可设置 0 ~ 104857600 MB。</p><p>它是<strong>全站共享的一个池</strong>：系统里所有人设成永久的文件加起来不能超过这个数。不是每人一份 —— 否则总量会随人数无限增长，磁盘迟早被撑爆。</p><p>用户点「设为永久」时会看到二次确认，里面显示已用多少、还剩多少；超出时无法再设，并提示还差多少。</p><div class="tip custom-block"><p class="custom-block-title">设为 0 = 关闭永久功能</p><p>填 <code>0</code> 就不提供「设为永久」这个入口，所有文件都按保留天数到期。</p></div><div class="warning custom-block"><p class="custom-block-title">已设为永久的文件不会被回收</p><p>把配额调小（甚至调到低于当前已用量）时，<strong>已经设成永久的文件不受影响</strong>， 只是新的「设为永久」会因为超额而被拒绝。避免&quot;改个配置就把用户的东西收走&quot;。</p></div><h2 id="允许上传" tabindex="-1">允许上传 <a class="header-anchor" href="#允许上传" aria-label="Permalink to &quot;允许上传&quot;">​</a></h2><p>总开关。关闭后所有用户都无法上传新文件，<strong>已上传的文件不受影响</strong>。</p><p>适合在维护、迁移或磁盘空间告急时临时关闭。</p><h2 id="关于到期的完整流程" tabindex="-1">关于到期的完整流程 <a class="header-anchor" href="#关于到期的完整流程" aria-label="Permalink to &quot;关于到期的完整流程&quot;">​</a></h2>`,41)),(a(),i(c,null,{default:o(()=>[p(e,{id:"mermaid-172",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E4%B8%8A%E4%BC%A0%5D%20--%3E%20B%5B%E6%9C%89%E6%95%88%5D%0A%20%20%20%20B%20--%20%22%E4%BF%9D%E7%95%99%E5%A4%A9%E6%95%B0%3Cbr%2F%3E%E9%BB%98%E8%AE%A4%2015%20%E5%A4%A9%22%20--%3E%20C%5B%E5%9B%9E%E6%94%B6%E7%AB%99%5D%0A%20%20%20%20C%20--%20%22%E5%9B%9E%E6%94%B6%E7%AB%99%E5%A4%A9%E6%95%B0%3Cbr%2F%3E%E9%BB%98%E8%AE%A4%207%20%E5%A4%A9%22%20--%3E%20D%5B%E5%BD%BB%E5%BA%95%E5%88%A0%E9%99%A4%5D%0A%20%20%20%20C%20--%20%22%E7%AE%A1%E7%90%86%E5%91%98%E6%81%A2%E5%A4%8D%22%20--%3E%20B%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=s('<p>两个天数共同决定了文件在服务器上最多保留多久。默认配置下最长约 <strong>22 天</strong>。</p><h2 id="存储一致性检查" tabindex="-1">存储一致性检查 <a class="header-anchor" href="#存储一致性检查" aria-label="Permalink to &quot;存储一致性检查&quot;">​</a></h2><p>用于确认<strong>数据库记录与磁盘文件是否一致</strong>，点击「扫描」执行。</p><p>扫描结果分三类：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>处理方式</th></tr></thead><tbody><tr><td>孤儿文件</td><td>磁盘上有文件，但数据库里没有记录</td><td>系统会自动归档到临时目录并保留 7 天后删除</td></tr><tr><td>缺失文件</td><td>数据库有记录，但磁盘上的文件不见了</td><td>说明文件被误删或磁盘故障，需要从备份恢复</td></tr><tr><td>非法路径</td><td>数据库里出现了不合法的路径</td><td>属于异常数据，建议联系开发者排查</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">什么时候用</p><ul><li>怀疑有文件丢失时</li><li>手动操作过服务器上的文件或目录后</li><li>定期巡检（例如每月一次）</li></ul><p>三项都为 0 表示数据库与磁盘完全对应，这是正常状态。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./files">文件与回收站</a></li><li><a href="./workbench">工作台</a></li></ul>',8))])}const _=l(h,[["render",g]]);export{k as __pageData,_ as default};
